import os
import ast

def analyze_repo():
    app_dir = "app"
    results = []
    for root, dirs, files in os.walk(app_dir):
        for file in files:
            if not file.endswith(".py") or file == "auth.py":
                continue
            path = os.path.join(root, file)
            with open(path, "r", encoding="utf-8") as f:
                content = f.read()
            if "legacy_auth" not in content:
                continue

            try:
                tree = ast.parse(content)
            except SyntaxError as e:
                print(f"Syntax error in {path}: {e}")
                continue

            # Find functions
            for node in ast.walk(tree):
                if isinstance(node, ast.FunctionDef):
                    # Check if legacy_auth is called in this function
                    has_legacy_auth = False
                    for child in ast.walk(node):
                        if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == "legacy_auth":
                            has_legacy_auth = True
                            break
                    if has_legacy_auth:
                        # Get function source from content using node's lines
                        # (note: AST line numbers are 1-based)
                        lines = content.splitlines()
                        func_lines = lines[node.lineno-1:node.end_lineno]
                        func_src = "\n".join(func_lines)

                        # Search for write/mutation keywords in the function definition/body
                        keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]
                        matches = [kw for kw in keywords if kw in func_src]

                        results.append({
                            "path": path,
                            "func_name": node.name,
                            "matches": matches,
                            "src": func_src
                        })
    for r in results:
        print(f"File: {r['path']} | Func: {r['func_name']} | Matches: {r['matches']}")
        # print(r['src'])
        # print("-" * 40)

if __name__ == "__main__":
    analyze_repo()

